begin;
create table public.interview_story_prompts (
 id text primary key,
 category text not null,
 prompt text not null
);
alter table public.interview_story_prompts enable row level security;
create policy "Read story prompts" on public.interview_story_prompts for select to authenticated using(true);
revoke all on public.interview_story_prompts from public,anon,authenticated;
grant select on public.interview_story_prompts to authenticated;
grant all on public.interview_story_prompts to service_role;
alter table public.interview_stories add column prompt_id text references public.interview_story_prompts(id);
create index interview_stories_owner_prompt_idx on public.interview_stories(user_id,prompt_id) where prompt_id is not null;
grant insert(prompt_id),update(prompt_id) on public.interview_stories to authenticated;
-- Partial answers can be saved and resumed; existing completed stories are unchanged.
alter table public.interview_stories drop constraint interview_stories_context_check,
 drop constraint interview_stories_actions_check, drop constraint interview_stories_reflection_check;
alter table public.interview_stories add constraint interview_stories_context_check check(char_length(btrim(context))<=2000),
 add constraint interview_stories_actions_check check(char_length(btrim(actions))<=2000),
 add constraint interview_stories_reflection_check check(char_length(btrim(reflection))<=2000),
 add constraint interview_stories_has_content check(char_length(btrim(context))+char_length(btrim(actions))+char_length(btrim(reflection))>0);
commit;
